package com.rpscans.api.service;
import com.rpscans.api.dto.CreateVisitRequest; import com.rpscans.api.entity.*; import com.rpscans.api.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class VisitService { private final PatientRepository patients; private final ReferralPartyRepository refs; private final InvestigationRepository invs; private final VisitRepository visits; private final VisitInvestigationRepository items; private final PaymentRepository payments;
 public VisitService(PatientRepository a,ReferralPartyRepository b,InvestigationRepository c,VisitRepository d,VisitInvestigationRepository e,PaymentRepository f){patients=a;refs=b;invs=c;visits=d;items=e;payments=f;}
 @Transactional public Visit create(CreateVisitRequest r){ Visit v=new Visit(); v.patient=patients.findById(r.patientId()).orElseThrow(); v.visitDate=r.visitDate(); v.remarks=r.remarks(); if(r.referralPartyId()!=null)v.referralParty=refs.findById(r.referralPartyId()).orElseThrow(); BigDecimal gross=BigDecimal.ZERO,disc=BigDecimal.ZERO;
  if(r.investigations()!=null) for(var q:r.investigations()){gross=gross.add(q.amount());disc=disc.add(q.discountAmount()==null?BigDecimal.ZERO:q.discountAmount());} v.grossAmount=gross;v.discountAmount=disc;v.finalAmount=gross.subtract(disc);v=visits.save(v);
  if(r.investigations()!=null) for(var q:r.investigations()){VisitInvestigation x=new VisitInvestigation();x.visit=v;x.investigation=invs.findById(q.investigationId()).orElseThrow();x.amount=q.amount();x.concession=q.concession();x.discountAmount=q.discountAmount()==null?BigDecimal.ZERO:q.discountAmount();x.discountReason=q.discountReason();x.referralAmount=q.referralAmount()==null?BigDecimal.ZERO:q.referralAmount();items.save(x);} if(r.payments()!=null)for(var q:r.payments()){Payment p=new Payment();p.visit=v;p.mode=Payment.Mode.valueOf(q.mode().toUpperCase());p.amount=q.amount();p.referenceNo=q.referenceNo();payments.save(p);} return v; }
}
